let useIcons = true;
function fillPc(el, code, color) {
  if (useIcons && ICONS && ICONS[code]) { el.classList.add('icon'); el.innerHTML = ICONS[code][color]; }
  else { el.classList.remove('icon'); el.textContent = letters[code]; }
}
function pcHTML(code, color) {
  return useIcons && ICONS && ICONS[code] ? `<div class="pc ${color} icon">${ICONS[code][color]}</div>` : `<div class="pc ${color}">${letters[code]}</div>`;
}
for (const p of PIECES) p.comps = parse(p.betza);
const FILES = 'abcdefghij';
const sqName = i => FILES[i % 10] + (Math.floor(i / 10) + 1);
const store = {
  get(k) { try { return localStorage.getItem(k); } catch (e) { return null; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch (e) {} },
};
let letters = Object.fromEntries(PIECES.map(p => [p.code, p.code]));
try { const s = JSON.parse(store.get('fbv3-letters') || 'null'); if (s) Object.assign(letters, s); } catch (e) {}
let board = new Array(100).fill(null); // {c:'w'|'b', t:code, moved:bool}
let history = [];
let selected = -1, moves = [];
let flipped = false, placeType = 'K';
let drag = null;

const $ = id => document.getElementById(id);
const mode = () => document.querySelector('input[name=mode]:checked').value;
const color = () => document.querySelector('input[name=color]:checked').value;
const attSide = () => document.querySelector('input[name=att]:checked').value;

function snapshot() { history.push(JSON.stringify(board)); if (history.length > 300) history.shift(); }
function save() { store.set('fbv3-board', toCode()); }

function sideBoard(c) { // bàn nhìn từ phe c: 1 = quân mình, 2 = quân đối phương
  const b = new Int8Array(100);
  for (let i = 0; i < 100; i++) if (board[i]) b[i] = board[i].c === c ? 1 : 2;
  return b;
}
function movesOf(i) {
  const p = board[i]; if (!p) return [];
  const b = sideBoard(p.c);
  return genMoves(b, BY[p.t].comps, i % 10, Math.floor(i / 10), p.c === 'w' ? 1 : -1, p.moved);
}
function attackers(c) { // số quân phe c có thể ăn ở mỗi ô (ô trống tính như có quân đối phương đứng đó)
  const cnt = new Array(100).fill(0);
  const pcs = []; for (let i = 0; i < 100; i++) if (board[i] && board[i].c === c) pcs.push(i);
  for (let s = 0; s < 100; s++) {
    if (board[s] && board[s].c === c) continue;
    const b = sideBoard(c); if (!board[s]) b[s] = 2;
    for (const i of pcs) {
      const p = board[i];
      const mv = genMoves(b, BY[p.t].comps, i % 10, Math.floor(i / 10), c === 'w' ? 1 : -1, p.moved);
      if (mv.some(m => m.caps.includes(s))) cnt[s]++;
    }
  }
  return cnt;
}
function inCheck(c) {
  let k = -1; for (let i = 0; i < 100; i++) if (board[i] && board[i].c === c && BY[board[i].t].royal) { k = i; break; }
  if (k < 0) return -1;
  const o = c === 'w' ? 'b' : 'w';
  for (let i = 0; i < 100; i++) if (board[i] && board[i].c === o) if (movesOf(i).some(m => m.caps.includes(k))) return k;
  return -1;
}

function render() {
  const el = $('board'); el.innerHTML = '';
  const mvTo = new Map(); for (const m of moves) mvTo.set(m.to, m);
  const hSet = new Set(); for (const m of moves) for (const c of m.caps) if (c !== m.to) hSet.add(c);
  const att = attSide() ? attackers(attSide()) : null;
  const chk = new Set([inCheck('w'), inCheck('b')]);
  for (let r = 0; r < 10; r++) {
    const y = flipped ? r : 9 - r;
    const lab = document.createElement('div'); lab.className = 'coord'; lab.textContent = y + 1; el.appendChild(lab);
    for (let cc = 0; cc < 10; cc++) {
      const x = flipped ? 9 - cc : cc, i = y * 10 + x;
      const d = document.createElement('div');
      d.className = 'sq ' + ((x + y) % 2 ? 'l' : 'd');
      d.dataset.i = i;
      const m = mvTo.get(i);
      if (m) d.classList.add(m.caps.some(c => c !== m.to) ? 'cj' : 'mv');
      if (i === selected) d.classList.add('selected');
      if (hSet.has(i)) { const x2 = document.createElement('span'); x2.className = 'x'; x2.textContent = 'X'; d.appendChild(x2); }
      const p = board[i];
      if (p) {
        const pc = document.createElement('div');
        pc.className = 'pc ' + p.c + (p.moved ? '' : ' unmoved') + (chk.has(i) ? ' chk' : '');
        fillPc(pc, p.t, p.c);
        pc.title = BY[p.t].name + ' ' + BY[p.t].betza;
        d.appendChild(pc);
      }
      if (att && att[i]) { const a = document.createElement('span'); a.className = 'att'; a.textContent = att[i]; d.appendChild(a); }
      el.appendChild(d);
    }
  }
  el.appendChild(document.createElement('div'));
  for (let cc = 0; cc < 10; cc++) { const lab = document.createElement('div'); lab.className = 'coord'; lab.textContent = FILES[flipped ? 9 - cc : cc]; el.appendChild(lab); }
  renderInfo(); renderStats(); $('code').value = toCode(); save();
}
function renderInfo() {
  if (selected < 0 || !board[selected]) { $('info').innerHTML = '<span class="muted">Chưa chọn quân nào.</span>'; return; }
  const p = board[selected], d = BY[p.t];
  const caps = moves.filter(m => m.caps.length).length;
  $('info').innerHTML = `<b>${d.name}</b> (${p.c === 'w' ? 'Trắng' : 'Đen'}) ở <b>${sqName(selected)}</b> · <code>${d.betza}</code><br>` +
    `${moves.length} nước đi, trong đó ${caps} nước ăn quân. Giá trị: ${d.royal ? '(hoàng gia) ' : ''}${d.v.map(x => x.toFixed(2)).join(' / ')}${p.moved ? ' · đã đi' : ' · chưa đi'}`;
}
function renderStats() {
  const s = { w: { n: 0, v: [0, 0, 0], k: 0 }, b: { n: 0, v: [0, 0, 0], k: 0 } };
  const per = { w: {}, b: {} };
  for (const p of board) if (p) {
    const S = s[p.c], d = BY[p.t]; S.n++; per[p.c][p.t] = (per[p.c][p.t] || 0) + 1;
    if (d.royal) S.k++; else d.v.forEach((x, j) => S.v[j] += x);
  }
  const f = x => x.toFixed(2);
  let h = '<tr><th></th><th class="num">Số quân</th><th class="num">Khai</th><th class="num">Trung</th><th class="num">Tàn</th></tr>';
  for (const c of ['w', 'b']) h += `<tr><td>${c === 'w' ? 'Trắng' : 'Đen'}</td><td class="num">${s[c].n} / 30${s[c].k !== 1 ? ' ⚠' : ''}</td>${s[c].v.map(x => `<td class="num">${f(x)}</td>`).join('')}</tr>`;
  h += `<tr><td>Chênh lệch</td><td class="num">${s.w.n - s.b.n}</td>${s.w.v.map((x, j) => `<td class="num">${f(x - s.b.v[j])}</td>`).join('')}</tr>`;
  $('stats').innerHTML = h;
  // bảng loại quân kèm số lượng mỗi bên
  let t = '<tr><th></th><th>Mã</th><th>Chữ</th><th>Quân</th><th>Betza</th><th class="num">TB</th><th class="num">T</th><th class="num">Đ</th></tr>';
  for (const p of PIECES) t += `<tr><td>${pcHTML(p.code, 'w')}</td><td>${p.code}</td><td><input maxlength="2" data-code="${p.code}" value="${letters[p.code]}"></td><td>${p.name}</td><td><code>${p.betza}</code></td>` +
    `<td class="num">${p.royal ? '–' : f((p.v[0] + p.v[1] + p.v[2]) / 3)}</td><td class="num">${per.w[p.code] || 0}</td><td class="num">${per.b[p.code] || 0}</td></tr>`;
  if (!document.activeElement || !document.activeElement.dataset || !document.activeElement.dataset.code) $('legendtbl').innerHTML = t;
}
function renderPalette() {
  const el = $('palette'); el.innerHTML = '';
  for (const p of PIECES) {
    const b = document.createElement('button');
    b.className = p.code === placeType ? 'on' : '';
    b.title = p.name + ' ' + p.betza;
    b.innerHTML = `${pcHTML(p.code, color())}<small>${p.name}</small>`;
    b.onclick = () => { placeType = p.code; $('m-place').checked = true; selected = -1; moves = []; renderPalette(); render(); };
    el.appendChild(b);
  }
}

// ----- tương tác bàn cờ -----
function squareAt(x, y) { const e = document.elementFromPoint(x, y); const s = e && e.closest && e.closest('.sq'); return s ? Number(s.dataset.i) : -1; }
function clickSquare(i) {
  const md = mode();
  if (md === 'place') { snapshot(); board[i] = { c: color(), t: placeType, moved: false }; selected = -1; moves = []; render(); return; }
  if (md === 'erase') { if (board[i]) { snapshot(); board[i] = null; } selected = -1; moves = []; render(); return; }
  const m = moves.find(m => m.to === i);
  if (selected >= 0 && m) {
    snapshot();
    const p = board[selected];
    for (const c of m.caps) board[c] = null;
    board[selected] = null; board[i] = { ...p, moved: true };
    selected = i; moves = movesOf(i); render(); return;
  }
  if (board[i]) { selected = i; moves = movesOf(i); } else { selected = -1; moves = []; }
  render();
}
$('board').addEventListener('contextmenu', e => {
  e.preventDefault(); const i = squareAt(e.clientX, e.clientY);
  if (i >= 0 && board[i]) { snapshot(); board[i] = null; if (selected === i) { selected = -1; moves = []; } else if (selected >= 0) moves = movesOf(selected); render(); }
});
$('board').addEventListener('pointerdown', e => {
  if (e.button !== 0) return;
  const i = squareAt(e.clientX, e.clientY); if (i < 0) return;
  drag = { from: i, x: e.clientX, y: e.clientY, moved: false, ghost: null };
});
window.addEventListener('pointermove', e => {
  if (!drag) return;
  if (!drag.moved && Math.hypot(e.clientX - drag.x, e.clientY - drag.y) > 6 && board[drag.from] && mode() !== 'erase') {
    drag.moved = true;
    const p = board[drag.from];
    const g = document.createElement('div'); g.className = 'pc ' + p.c + ' ghost'; fillPc(g, p.t, p.c); document.body.appendChild(g); drag.ghost = g;
  }
  if (drag.ghost) { drag.ghost.style.left = e.clientX + 'px'; drag.ghost.style.top = e.clientY + 'px'; }
});
window.addEventListener('pointerup', e => {
  if (!drag) return;
  const d = drag; drag = null;
  if (d.ghost) d.ghost.remove();
  const to = squareAt(e.clientX, e.clientY);
  if (!d.moved) { if (to === d.from) clickSquare(to); return; }
  if (to < 0) { snapshot(); board[d.from] = null; selected = -1; moves = []; render(); return; } // kéo ra ngoài bàn = xóa
  if (to === d.from) return;
  snapshot();
  board[to] = board[d.from]; board[d.from] = null;
  selected = to; moves = movesOf(to); render();
});

// ----- mã thế cờ -----
function toCode() {
  const rows = [];
  for (let y = 9; y >= 0; y--) {
    let r = '', e = 0;
    for (let x = 0; x < 10; x++) {
      const p = board[y * 10 + x];
      if (!p) { e++; continue; }
      if (e) { r += e; e = 0; }
      r += p.c === 'w' ? p.t : p.t.toLowerCase();
    }
    if (e) r += e;
    rows.push(r);
  }
  return rows.join('/');
}
function fromCode(s) {
  const rows = s.trim().split('/');
  if (rows.length !== 10) throw new Error('cần đúng 10 hàng');
  const nb = new Array(100).fill(null);
  rows.forEach((r, k) => {
    const y = 9 - k; let x = 0, j = 0;
    while (j < r.length) {
      const m = /^\d+/.exec(r.slice(j));
      if (m) { x += Number(m[0]); j += m[0].length; continue; }
      const ch = r[j++], up = ch.toUpperCase();
      if (!BY[up]) throw new Error('chữ lạ: ' + ch);
      if (x > 9) throw new Error('hàng ' + (y + 1) + ' quá 10 ô');
      nb[y * 10 + x] = { c: ch === up ? 'w' : 'b', t: up, moved: false }; x++;
    }
    if (x !== 10) throw new Error('hàng ' + (y + 1) + ' có ' + x + ' ô');
  });
  return nb;
}

// ----- nút -----
$('undo').onclick = () => { if (!history.length) return; board = JSON.parse(history.pop()); selected = -1; moves = []; render(); };
$('clear').onclick = () => { snapshot(); board = new Array(100).fill(null); selected = -1; moves = []; render(); };
$('flip').onclick = () => { flipped = !flipped; render(); };
$('fresh').onclick = () => { snapshot(); board = board.map(p => p && { ...p, moved: false }); if (selected >= 0) moves = movesOf(selected); render(); };
function mirror(central) {
  snapshot();
  for (let i = 0; i < 100; i++) if (board[i] && board[i].c === 'b') board[i] = null;
  const nb = board.slice();
  for (let i = 0; i < 100; i++) {
    const p = board[i]; if (!p || p.c !== 'w') continue;
    const x = i % 10, y = Math.floor(i / 10);
    const j = (9 - y) * 10 + (central ? 9 - x : x);
    if (nb[j] && nb[j].c === 'w') continue;
    nb[j] = { c: 'b', t: p.t, moved: false };
  }
  board = nb; selected = -1; moves = []; render();
}
$('mirrorH').onclick = () => mirror(false);
$('mirrorC').onclick = () => mirror(true);
$('load').onclick = () => { try { const nb = fromCode($('code').value); snapshot(); board = nb; selected = -1; moves = []; $('codemsg').textContent = 'Đã nạp.'; render(); } catch (e) { $('codemsg').textContent = 'Lỗi: ' + e.message; } };
document.querySelectorAll('.preset').forEach(btn => btn.onclick = () => { snapshot(); board = fromCode(btn.dataset.code); selected = -1; moves = []; render(); });
// ----- bộ sinh thế khởi đầu ngẫu nhiên (chạy ở luồng nền) -----
function randomWorkerMain() {
  const MAP = { A: 'F2t[WFF]', B: 'vWFFmWWcpWW', C: 'CHmFF[cj1]FF', D: 'NmF4cpF4', E: 'FZgF3', F: 'DHfrClfCblCrbC', G: 'WGgW3', H: 'sDt[WnA]', J: 'ZnD', L: 'nGsWWvW', M: 'nNfrNlfNblNrbN', N: 'nN[cj]nN', K: 'WFmnDmnAmnN', P: 'mfWcfFimfnD', T: 'fKifmnDifmnA' };
  const comps = {}; for (const k in MAP) comps[k] = parse(MAP[k]);
  const FIXED = { 21: 'P', 22: 'P', 23: 'P', 24: 'P', 25: 'P', 26: 'P', 27: 'P', 28: 'P', 11: 'T', 13: 'T', 16: 'T', 18: 'T' };
  const R23 = [20, 29, 10, 12, 14, 15, 17, 19]; // a3 j3 a2 c2 e2 f2 h2 j2
  const rnd = () => { const a = new Uint32Array(1); crypto.getRandomValues(a); return a[0] / 4294967296; };
  const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  function propose() {
    let r23; do { r23 = shuffle('HHLLMMNN'.split('')); } while (r23[0] === 'H' || r23[1] === 'H');
    const X = 'ABCDEFGJ'[Math.floor(rnd() * 8)];
    const kx = rnd() < 0.5 ? 4 : 5;
    const rest = shuffle(('ABCDEFGJ' + X).split(''));
    const b = new Array(100).fill(null);
    const put = (i, t) => { b[i] = { c: 'w', t, moved: false }; const x = i % 10, y = Math.floor(i / 10); b[(9 - y) * 10 + x] = { c: 'b', t, moved: false }; };
    for (const i in FIXED) put(+i, FIXED[i]);
    R23.forEach((sq, k) => put(sq, r23[k]));
    for (let x = 0, j = 0; x < 10; x++) put(x, x === kx ? 'K' : rest[j++]);
    return b;
  }
  const gen = (bb, c) => { const a = new Int8Array(100); for (let i = 0; i < 100; i++) if (bb[i]) a[i] = bb[i].c === c ? 1 : 2; const o = [];
    for (let i = 0; i < 100; i++) { const p = bb[i]; if (!p || p.c !== c) continue; for (const m of genMoves(a, comps[p.t], i % 10, Math.floor(i / 10), c === 'w' ? 1 : -1, p.moved)) o.push({ from: i, to: m.to, caps: m.caps }); } return o; };
  const apply = (bb, m) => { const nb = bb.slice(); const p = nb[m.from]; for (const c of m.caps) nb[c] = null; nb[m.from] = null; nb[m.to] = { c: p.c, t: p.t, moved: true }; return nb; };
  const opp = c => c === 'w' ? 'b' : 'w';
  function cond1(b) { for (const c of ['w', 'b']) for (const m1 of gen(b, c)) { if (m1.caps.length) return false; if (gen(apply(b, m1), c).some(m => m.caps.length)) return false; } return true; }
  // tập độ lệch (hệ của quân) mà quân có thể ăn tới; dùng để bỏ qua quân không thể đánh tới vua
  function capDisp(cs) {
    const set = new Set(); const add = (x, y) => { if (Math.abs(x) <= 9 && Math.abs(y) <= 9) set.add(x * 100 + y); };
    for (const c of cs) {
      if (c.kind === 'step') { if (!c.modality.includes('c')) continue; for (const v of c.vecs) for (let k = 1; k <= Math.min(c.amax, 9); k++) add(v[0] * k, v[1] * k); }
      else if (c.kind === 'hop') { if (!c.modality.includes('c')) continue; const bm = c.hop === 'g' ? 1 : Math.min(c.amax, 9);
        for (const v of c.vecs) for (let a = 1; a <= Math.min(c.amax, 9); a++) for (let b = 1; b <= bm; b++) add(v[0] * (a + b), v[1] * (a + b)); }
      else if (c.kind === 'cj') { for (const v of c.vecs) for (let a = 1; a <= Math.min(c.amax, 9); a++) add(v[0] * a, v[1] * a); }
      else if (c.kind === 't') { for (const u of c.A.vecs) { add(u[0], u[1]); const dirs = c.B.cluster ? c.B.vecs : c.B.vecs.filter(d => u[0] * d[0] + u[1] * d[1] > 0);
        for (const d of dirs) for (let k = 1; k <= Math.min(c.B.amax, 9); k++) add(u[0] + d[0] * k, u[1] + d[1] * k); } }
    }
    return set;
  }
  const DISP = {}; for (const k in comps) DISP[k] = capDisp(comps[k]);
  const sideArr = (bb, c) => { const a = new Int8Array(100); for (let i = 0; i < 100; i++) if (bb[i]) a[i] = bb[i].c === c ? 1 : 2; return a; };
  function attacked(bb, c) {
    const k = bb.findIndex(p => p && p.c === opp(c) && p.t === 'K'); if (k < 0) return false;
    const kx = k % 10, ky = Math.floor(k / 10), sd = c === 'w' ? 1 : -1; let a = null;
    for (let i = 0; i < 100; i++) {
      const p = bb[i]; if (!p || p.c !== c) continue;
      const dx = (kx - i % 10) * sd, dy = (ky - Math.floor(i / 10)) * sd;
      if (!DISP[p.t].has(dx * 100 + dy)) continue;
      if (!a) a = sideArr(bb, c);
      for (const m of genMoves(a, comps[p.t], i % 10, Math.floor(i / 10), sd, p.moved)) if (m.caps.includes(k)) return true;
    }
    return false;
  }
  const legal = (bb, c) => gen(bb, c).filter(m => !attacked(apply(bb, m), opp(c)));
  function cond2(b) {
    for (const c of ['w', 'b']) { const o = opp(c);
      for (const m1 of legal(b, c)) { const b1 = apply(b, m1); if (attacked(b1, c)) return false;
        if (!gen(b1, c).some(m3 => attacked(apply(b1, m3), c))) continue;
        let ref = false; for (const r of legal(b1, o)) { const b2 = apply(b1, r); if (!legal(b2, c).some(m3 => attacked(apply(b2, m3), c))) { ref = true; break; } }
        if (!ref) return false; } }
    return true;
  }
  function code(b) { const rows = []; for (let y = 9; y >= 0; y--) { let r = '', e = 0; for (let x = 0; x < 10; x++) { const p = b[y * 10 + x]; if (!p) { e++; continue; } if (e) { r += e; e = 0; } r += p.c === 'w' ? p.t : p.t.toLowerCase(); } if (e) r += e; rows.push(r); } return rows.join('/'); }
  self.onmessage = () => {
    let tries = 0; const t0 = Date.now();
    for (;;) {
      tries++;
      const b = propose();
      if (cond1(b) && cond2(b)) { self.postMessage({ done: true, code: code(b), tries, ms: Date.now() - t0 }); return; }
      if (tries % 5 === 0) self.postMessage({ done: false, tries, ms: Date.now() - t0 });
    }
  };
}
let randWorker = null;
function stopRandom(msg) { if (randWorker) { randWorker.terminate(); randWorker = null; } $('rand').disabled = false; $('randStop').style.display = 'none'; if (msg !== undefined) $('randmsg').textContent = msg; }
$('rand').onclick = () => {
  stopRandom();
  try {
    const src = document.getElementById('engine').textContent + String.fromCharCode(10) + '(' + randomWorkerMain.toString() + ')();';
    randWorker = new Worker(URL.createObjectURL(new Blob([src], { type: 'text/javascript' })));
  } catch (e) { $('randmsg').textContent = 'Trình duyệt không cho chạy luồng nền: ' + e.message; return; }
  $('rand').disabled = true; $('randStop').style.display = ''; $('randmsg').textContent = 'Đang tìm…';
  randWorker.onmessage = ev => {
    const d = ev.data;
    if (!d.done) { $('randmsg').textContent = `Đang tìm… đã thử ${d.tries} thế (${(d.ms / 1000).toFixed(1)} giây)`; return; }
    stopRandom(`Xong: thử ${d.tries} thế, ${(d.ms / 1000).toFixed(1)} giây.`);
    snapshot(); board = fromCode(d.code); selected = -1; moves = []; render();
  };
  randWorker.onerror = e => stopRandom('Lỗi: ' + e.message);
};
$('randStop').onclick = () => stopRandom('Đã dừng.');
$('copy').onclick = async () => { try { await navigator.clipboard.writeText(toCode()); $('codemsg').textContent = 'Đã chép.'; } catch (e) { $('code').select(); $('codemsg').textContent = 'Hãy bấm Ctrl+C.'; } };
document.querySelectorAll('input[name=att]').forEach(r => r.onchange = render);
document.querySelectorAll('input[name=color]').forEach(r => r.onchange = renderPalette);
document.querySelectorAll('input[name=mode]').forEach(r => r.onchange = () => { selected = -1; moves = []; render(); });
$('legendtbl').addEventListener('input', e => {
  const c = e.target.dataset.code; if (!c) return;
  letters[c] = e.target.value.trim() || c; store.set('fbv3-letters', JSON.stringify(letters)); renderPalette(); render();
});
document.addEventListener('keydown', e => { if ((e.ctrlKey || e.metaKey) && e.key === 'z' && e.target.tagName !== 'TEXTAREA' && e.target.tagName !== 'INPUT') { e.preventDefault(); $('undo').onclick(); } });

try { const v = store.get('fbv3-icons'); if (v !== null) useIcons = v === '1'; } catch (e) {}
$('useIcons').checked = useIcons;
$('useIcons').onchange = () => { useIcons = $('useIcons').checked; store.set('fbv3-icons', useIcons ? '1' : '0'); renderPalette(); $('legendtbl').innerHTML = ''; render(); };
try { const s = store.get('fbv3-board'); board = fromCode(s || document.querySelector('.preset').dataset.code); } catch (e) {}
renderPalette(); render();
